package com.worklink.controller;
import com.worklink.dto.project.ProjectResponse;import com.worklink.service.ProjectService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/projects") @PreAuthorize("hasRole('FREELANCER')") public class MarketplaceProjectController {final ProjectService s;public MarketplaceProjectController(ProjectService x){s=x;}@GetMapping public List<ProjectResponse> all(){return s.published();}@GetMapping("/accepted") public List<ProjectResponse> accepted(){return s.activeForFreelancer();}@GetMapping("/{id}") public ProjectResponse one(@PathVariable Long id){return s.published(id);}}
